-- Synthetic identities, rollback-only. Real PostgreSQL RLS/ACL/transaction tests;
-- this does not assert hosted GoTrue, a mentor system or external AI availability.
begin;
create extension if not exists pgtap with schema extensions;
grant execute on all functions in schema extensions to authenticated,anon;
set local search_path=public,extensions;
select plan(30);
insert into auth.users(id,email) values('21000000-0000-4000-8000-000000000001','phase21-a@example.invalid'),('21000000-0000-4000-8000-000000000002','phase21-b@example.invalid');
create temp table test_input(value jsonb);
insert into test_input values(jsonb_build_object('id','21000000-0000-4000-8000-000000000003','requestId','21000000-0000-4000-8000-000000000004','version',0,'title','Қазақша essay','kind','personal_statement','content','My private experience 🙂','prompt','','wordLimit',null,'applicationId',null,'promptId',null,'rubric','{}'::jsonb,'studio','{"locale":"kk","archived":false}'::jsonb,'checkpoint',false));
grant select,update on test_input to authenticated;
set local role authenticated;
select set_config('request.jwt.claim.sub','21000000-0000-4000-8000-000000000001',true);
select is((public.writing_studio_save((select value from test_input))).version,1,'first autosave persists');
select is((select content from public.writing_drafts where id='21000000-0000-4000-8000-000000000003'),'My private experience 🙂','Unicode content persists');
select is((select count(*)::int from public.writing_versions where draft_id='21000000-0000-4000-8000-000000000003'),1,'first save checkpoints');
select is((public.writing_studio_save((select value from test_input))).version,1,'same request replays without duplicate');
select throws_ok($$select public.writing_studio_save((select value||'{"content":"different"}' from test_input))$$,'23514',null,'reusing request ID with different content denied');
update test_input set value=value||'{"requestId":"21000000-0000-4000-8000-000000000005","version":1,"content":"Revision two"}';
select is((public.writing_studio_save((select value from test_input))).version,2,'next autosave increments CAS');
select is((select count(*)::int from public.writing_versions where draft_id='21000000-0000-4000-8000-000000000003'),1,'autosave does not grow checkpoint history');
select throws_ok($$select public.writing_studio_save((select value||'{"requestId":"21000000-0000-4000-8000-000000000006","version":1,"content":"Stale tab"}' from test_input))$$,'40001',null,'stale tab cannot overwrite');
select is((select content from public.writing_drafts where id='21000000-0000-4000-8000-000000000003'),'Revision two','conflict preserves remote text');
select throws_ok($$select public.writing_studio_save((select value||'{"requestId":"21000000-0000-4000-8000-000000000004","version":0,"content":"My private experience 🙂"}' from test_input))$$,'40001',null,'uncertain old receipt never acknowledges newer content');
update test_input set value=value||'{"requestId":"21000000-0000-4000-8000-000000000007","version":2,"content":"My private experience 🙂","checkpoint":true}';
select is((public.writing_studio_save((select value from test_input))).version,3,'restore writes a new version');
select is((select count(*)::int from public.writing_versions where draft_id='21000000-0000-4000-8000-000000000003'),2,'restore retains original checkpoint');
select throws_ok($$update public.writing_versions set snapshot='{}'$$,'42501',null,'immutable versions deny direct writes');
select throws_ok($$update public.writing_drafts set content='forged'$$,'42501',null,'direct draft mutation denied');
select throws_ok($$select * from public.writing_save_receipts$$,'42501',null,'receipts are not exposed');
select set_config('request.jwt.claim.sub','21000000-0000-4000-8000-000000000002',true);
select is((select count(*)::int from public.writing_drafts),0,'user B cannot list A drafts');
select is((select count(*)::int from public.writing_versions),0,'user B cannot list A versions');
select throws_ok($$select public.writing_studio_save((select value||'{"requestId":"21000000-0000-4000-8000-000000000008","version":3}' from test_input))$$,'42501',null,'user B cannot guess and mutate A ID');
select set_config('request.jwt.claims','{"sub":"21000000-0000-4000-8000-000000000002","user_metadata":{"role":"mentor"}}',true);
select is((select count(*)::int from public.writing_drafts),0,'claimed mentor role grants no draft access');
reset role;
insert into public.writing_prompts(id,title,prompt,cycle,source_url,state) values('21000000-0000-4000-8000-000000000009','Unverified prompt','Do not trust this as official',2027,'https://example.invalid/source','draft');
set local role authenticated;
select set_config('request.jwt.claim.sub','21000000-0000-4000-8000-000000000001',true);
select is((select count(*)::int from public.writing_prompts),0,'unverified sources are invisible');
select throws_ok($$select public.writing_studio_save((select value||'{"requestId":"21000000-0000-4000-8000-000000000010","version":3,"promptId":"21000000-0000-4000-8000-000000000009"}' from test_input))$$,'23514',null,'unverified prompt cannot become official context');
select throws_ok($$insert into public.writing_prompts(title,prompt,cycle,source_url) values('Fake','Fake',2027,'https://example.invalid')$$,'42501',null,'student cannot publish invented requirements');
reset role;
update public.writing_prompts set state='verified',verified_at=now(),valid_until=current_date+1 where id='21000000-0000-4000-8000-000000000009';
set local role authenticated;
select is((select count(*)::int from public.writing_prompts),1,'current verified source is readable');
select is((public.writing_studio_save((select value||'{"requestId":"21000000-0000-4000-8000-000000000011","version":3,"promptId":"21000000-0000-4000-8000-000000000009","checkpoint":false}' from test_input))).version,4,'current source can be attached to own draft');
reset role;
update public.writing_prompts set valid_until=current_date-1 where id='21000000-0000-4000-8000-000000000009';
set local role authenticated;
select is((select count(*)::int from public.writing_prompts),0,'expired source fails closed');
select is((public.writing_studio_save((select value||'{"requestId":"21000000-0000-4000-8000-000000000012","version":4,"promptId":"21000000-0000-4000-8000-000000000009","checkpoint":false}' from test_input))).version,5,'expired existing context does not block draft preservation');
select throws_ok($$select public.writing_studio_save((select value||'{"id":"21000000-0000-4000-8000-000000000013","requestId":"21000000-0000-4000-8000-000000000014","version":0,"promptId":"21000000-0000-4000-8000-000000000009"}' from test_input))$$,'23514',null,'expired context cannot be newly selected');
reset role;
set local role anon;
select throws_ok($$select * from public.writing_drafts$$,'42501',null,'anonymous draft read denied');
select throws_ok($$select public.writing_studio_save('{}')$$,'42501',null,'anonymous command denied');
reset role;
select is((select count(*)::int from public.writing_drafts where user_id='21000000-0000-4000-8000-000000000001'),1,'negative cases leave only original project');
select * from finish();
rollback;
